function NormalizeImagePath(path) {
    if (!path) return "";
    let normalized = path;
    if (normalized.indexOf("s2r://") === 0) {
        normalized = normalized.substring("s2r://".length);
    } else if (normalized.indexOf("file://") === 0) {
        return normalized;
    }

    if (normalized.indexOf("panorama/") === 0) {
        normalized = normalized;
    }

    if (normalized.indexOf(".vtex_c") !== -1) {
        normalized = normalized.replace(/\.vtex_c$/i, ".vtex");
    }
    if (normalized.indexOf(".vsvg_c") !== -1) {
        normalized = normalized.replace(/\.vsvg_c$/i, ".vsvg");
    }

    const hasVtex = normalized.indexOf(".vtex") !== -1;
    const hasVsvg = normalized.indexOf(".vsvg") !== -1;
    if (!hasVtex && !hasVsvg) {
        normalized = normalized + ".vtex";
    }

    return "s2r://" + normalized;
}

